CREATE TYPE "PestClassification" AS ENUM ('INSECT','MITE','NEMATODE','MOLLUSK','RODENT','OTHER');
CREATE TYPE "PestSeverity" AS ENUM ('LOW','MODERATE','HIGH','CRITICAL');
CREATE TYPE "PestEconomicImpact" AS ENUM ('LOW','MODERATE','HIGH','SEVERE');
CREATE TYPE "PlantPestSusceptibility" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE "PlantPestRelationshipType" AS ENUM ('PRIMARY_HOST','SECONDARY_HOST','OCCASIONAL_HOST');
CREATE TABLE "Pest" ("id" TEXT PRIMARY KEY,"classification" "PestClassification" NOT NULL,"severity" "PestSeverity" NOT NULL,"economicImpact" "PestEconomicImpact" NOT NULL,"scientificName" TEXT,"description" TEXT,"createdByUserId" TEXT NOT NULL,"updatedByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PestAlias" ("id" TEXT PRIMARY KEY,"pestId" TEXT NOT NULL,"value" TEXT NOT NULL,"normalizedValue" TEXT NOT NULL,"locale" TEXT);
CREATE TABLE "PestSymptom" ("id" TEXT PRIMARY KEY,"pestId" TEXT NOT NULL,"value" TEXT NOT NULL,"normalizedValue" TEXT NOT NULL);
CREATE TABLE "PestDamagePattern" ("id" TEXT PRIMARY KEY,"pestId" TEXT NOT NULL,"value" TEXT NOT NULL,"normalizedValue" TEXT NOT NULL);
CREATE TABLE "PestLifecycleStage" ("id" TEXT PRIMARY KEY,"pestId" TEXT NOT NULL,"value" TEXT NOT NULL,"normalizedValue" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL);
CREATE TABLE "PlantPest" ("plantId" TEXT NOT NULL,"pestId" TEXT NOT NULL,"susceptibility" "PlantPestSusceptibility" NOT NULL,"relationshipType" "PlantPestRelationshipType" NOT NULL,"seasonalContext" TEXT,"notes" TEXT,PRIMARY KEY("plantId","pestId"));
CREATE TABLE "PestImage" ("id" TEXT PRIMARY KEY,"pestId" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"url" TEXT NOT NULL,"alt" TEXT NOT NULL,"contentType" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"width" INTEGER NOT NULL,"height" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PestKnowledgeSync" ("pestId" TEXT PRIMARY KEY,"status" "KnowledgeSyncStatus" NOT NULL DEFAULT 'PENDING',"lastSyncedAt" TIMESTAMP(3),"diagnosticCode" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "PestAlias_pestId_normalizedValue_key" ON "PestAlias"("pestId","normalizedValue"); CREATE UNIQUE INDEX "PestSymptom_pestId_normalizedValue_key" ON "PestSymptom"("pestId","normalizedValue"); CREATE UNIQUE INDEX "PestDamagePattern_pestId_normalizedValue_key" ON "PestDamagePattern"("pestId","normalizedValue"); CREATE UNIQUE INDEX "PestLifecycleStage_pestId_normalizedValue_key" ON "PestLifecycleStage"("pestId","normalizedValue"); CREATE UNIQUE INDEX "PestLifecycleStage_pestId_sortOrder_key" ON "PestLifecycleStage"("pestId","sortOrder"); CREATE UNIQUE INDEX "PestImage_storageKey_key" ON "PestImage"("storageKey"); CREATE UNIQUE INDEX "PestImage_pestId_sortOrder_key" ON "PestImage"("pestId","sortOrder");
CREATE INDEX "Pest_classification_idx" ON "Pest"("classification"); CREATE INDEX "Pest_severity_idx" ON "Pest"("severity"); CREATE INDEX "Pest_economicImpact_idx" ON "Pest"("economicImpact"); CREATE INDEX "Pest_createdByUserId_idx" ON "Pest"("createdByUserId"); CREATE INDEX "PlantPest_pestId_idx" ON "PlantPest"("pestId"); CREATE INDEX "PestKnowledgeSync_status_idx" ON "PestKnowledgeSync"("status");
ALTER TABLE "Pest" ADD FOREIGN KEY ("id") REFERENCES "KnowledgeEntity"("id") ON DELETE RESTRICT; ALTER TABLE "Pest" ADD FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT; ALTER TABLE "Pest" ADD FOREIGN KEY ("updatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT; ALTER TABLE "PestAlias" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PestSymptom" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PestDamagePattern" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PestLifecycleStage" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PlantPest" ADD FOREIGN KEY ("plantId") REFERENCES "Plant"("id") ON DELETE CASCADE; ALTER TABLE "PlantPest" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PestImage" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE; ALTER TABLE "PestKnowledgeSync" ADD FOREIGN KEY ("pestId") REFERENCES "Pest"("id") ON DELETE CASCADE;
